function lcs_of_three(X, Y, Z) {
  let m = X.length;
  let n = Y.length;
  let o = Z.length;

  // Create a 3D DP table to store lengths of LCS of substrings of X, Y, and Z
  let dp = new Array(m + 1).fill(null).map(() => 
    new Array(n + 1).fill(null).map(() => 
      new Array(o + 1).fill(0)
    )
  );

  // Build the dp table
  for (let i = 1; i <= m; i++) {
    for (let j = 1; j <= n; j++) {
      for (let k = 1; k <= o; k++) {
        if (X[i - 1] === Y[j - 1] && Y[j - 1] === Z[k - 1]) {
          dp[i][j][k] = dp[i - 1][j - 1][k - 1] + 1;
        } else {
          dp[i][j][k] = Math.max(
            dp[i - 1][j][k],
            dp[i][j - 1][k],
            dp[i][j][k - 1]
          );
        }
      }
    }
  }

  // The length of the longest common subsequence of X, Y, and Z
  return dp[m][n][o];
}

